from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.post import db_markers
from taf.ul.sc.perf.util.robot_helpers import mark_test_case_as_failed, get_builtin_value
from taf.ul.sc.perf.util.logger import log_info_to_console


def validate_test_results():
    if tc.is_feature_enabled("validate_test_results"):
        logs_url_msg = "Test case logs available at:\n{}".format(tc.logs_url)
        log_info_to_console(logs_url_msg)

        teb_msg = "Test Case {}. More details available at TEB validation:\n{}". \
            format(tc.current_test_case_status, tc.validation_url_link)
        if tc.current_test_case_status == 'FAILED':
            mark_test_case_as_failed(msg=teb_msg)
        else:
            log_info_to_console(teb_msg)
    else:
        log_info_to_console("Skipping test results validation. If not intended please check test case configuration.")


def set_test_status():
    """
    Print test case results to Log. It's works only in teardown section.

    :return: None
    """
    robot_test_status = get_builtin_value('TEST STATUS', None)
    if robot_test_status:
        test_status = 'PASSED' if robot_test_status == 'PASS' else 'FAILED'
        db_markers.add_test_status(test_status=test_status)
